/* Opaque iframe: local semantic mapping of canonical OpenDesk tokens; no host CSS. */
:root{color-scheme:light dark;--ink:#1b2c49;--sub:#53647e;--line:#e1e8f1;--brand:#365eda;--paper:#fff;--bg:#f5f7fb;--input-border:#7f8da1;--negative:#ae3d4b;--focus:#365eda;--space-1:4px;--space-2:8px;--space-3:12px;--space-4:16px;--radius-control:8px;--radius-surface:12px}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:13px/1.5 system-ui,sans-serif}
.capture-app{padding:var(--space-3);display:grid;gap:var(--space-4);min-width:0}section{display:grid;gap:var(--space-2);min-width:0}section+section{border-top:1px solid var(--line);padding-top:var(--space-4)}
h2,p,dl{margin:0}h2{font-size:14px}.secondary{font-size:12px;color:var(--sub);overflow-wrap:anywhere}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2)}.toolbar h2{flex:1}label{font-weight:600}
button,input,textarea{font:inherit;border:1px solid var(--input-border);border-radius:var(--radius-control);color:var(--ink);background:var(--paper);min-height:36px;padding:var(--space-2)}button{cursor:pointer}button:disabled{opacity:.55;cursor:default}button.primary{background:var(--brand);color:#fff;border-color:var(--brand)}input,textarea{width:100%;min-width:0}textarea{resize:vertical;font-family:ui-monospace,monospace}.actions{margin-top:var(--space-1)}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}.status-grid{display:grid;grid-template-columns:auto minmax(0,1fr);gap:var(--space-1) var(--space-3)}dt{color:var(--sub)}dd{margin:0;overflow-wrap:anywhere}pre{margin:0;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius-control);padding:var(--space-3);white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;font-size:12px}#app-error,#config-error{color:var(--negative)}#conflict{padding:var(--space-2);border:1px solid var(--input-border);border-radius:var(--radius-control)}[hidden]{display:none!important}
@media(prefers-color-scheme:dark){:root{--ink:#e9eef7;--sub:#b3c1d3;--line:#374457;--brand:#3566ba;--paper:#151c28;--bg:#101722;--input-border:#6d809b;--negative:#ff9ea6;--focus:#9dc1ff}}
@media(pointer:coarse){button,input{min-height:44px}}

